mapper.insert:
insert into sys_user_role(user_code, role_code) select requested.user_code, requested.role_code from (
select #{item.userCode} as user_code, #{item.roleCode} as role_code
) requested join sys_role r on r.role_code = requested.role_code where r.role_type = 'PLATFORM' and r.shop_code = '' and r.del_flag = '0'
